SHOW GLOBAL VARIABLES LIKE 'log_bin';
SHOW GLOBAL VARIABLES LIKE 'binlog_format';
SHOW BINARY LOGS;

-- 原生阅读前置：binlog.000012存在，且更早日志已确认不再需要
PURGE BINARY LOGS TO 'binlog.000012';
SHOW BINARY LOGS;

-- 前置：受控管理员会话，无活动事务
SET @saved_sql_log_bin=@@SESSION.sql_log_bin;
SET SESSION sql_log_bin=OFF;
SELECT @@SESSION.sql_log_bin AS session_logging;
SET SESSION sql_log_bin=@saved_sql_log_bin;

SHOW GLOBAL VARIABLES LIKE 'log_error';
SHOW GLOBAL VARIABLES LIKE 'log_error_services';
SHOW GLOBAL VARIABLES LIKE 'log_error_verbosity';

SHOW GLOBAL VARIABLES LIKE 'general_log';
SHOW GLOBAL VARIABLES LIKE 'log_output';
-- 已记录原设置并确认测试范围后，阅读以下变更
SET GLOBAL log_output='TABLE';
SET GLOBAL general_log=ON;

-- 前置：已启用TABLE目的地且当前账户允许读取日志表
SELECT event_time,thread_id,command_type,argument
FROM mysql.general_log ORDER BY event_time DESC LIMIT 5;

SHOW GLOBAL VARIABLES LIKE 'log_output';
SET GLOBAL slow_query_log=ON;
SET SESSION long_query_time=0.5;
SET SESSION min_examined_row_limit=0;
SELECT @@SESSION.long_query_time AS threshold_seconds;

-- 前置：慢日志选择TABLE且当前账户可读
SELECT start_time,query_time,lock_time,rows_sent,rows_examined,sql_text
FROM mysql.slow_log ORDER BY start_time DESC LIMIT 5;
